/**
 * Sync skill/democrito/ reference files from canonical docs/ sources.
 *
 * Run automatically as part of `npm run build`. Do not edit skill files directly —
 * edit the source in docs/ and rebuild.
 *
 * Outputs:
 *   skill/democrito/principles.md  ← docs/reference/principles.md
 *   skill/democrito/tokens.md      ← docs/reference/tokens.md
 *   skill/democrito/components.md  ← docs/components/{atoms,molecules,organisms,templates}.md
 *   skill/democrito/agent-usage.md ← docs/ai/{README,terminal,lovable,replit,cursor}.md
 */

import { readFileSync, writeFileSync } from "node:fs";
import { resolve, join } from "node:path";

const root = resolve(".");

function read(path) {
  return readFileSync(join(root, path), "utf8");
}

function write(path, content) {
  writeFileSync(join(root, path), content, "utf8");
}

/**
 * Strip relative markdown links — [text](./path) or [text](../path) — to plain text.
 * Absolute URLs (http/https) are preserved.
 */
function flattenRelativeLinks(content) {
  return content.replace(
    /\[([^\]]+)\]\((?!https?:\/\/)\.{1,2}[./][^)]*\)/g,
    "$1"
  );
}

const GENERATED_HEADER =
  "<!-- Generated by scripts/sync-skill-docs.mjs — edit docs/, not this file. -->\n\n";

// 1. principles.md
const principles = read("docs/reference/principles.md");
write(
  "skill/democrito/principles.md",
  GENERATED_HEADER + flattenRelativeLinks(principles)
);
console.log("✓ skill/democrito/principles.md");

// 2. tokens.md
const tokens = read("docs/reference/tokens.md");
write(
  "skill/democrito/tokens.md",
  GENERATED_HEADER + flattenRelativeLinks(tokens)
);
console.log("✓ skill/democrito/tokens.md");

// 3. components.md — concat four tiers
const COMPONENT_TIERS = ["atoms", "molecules", "organisms", "templates"];
const componentParts = COMPONENT_TIERS.map((tier) =>
  flattenRelativeLinks(read(`docs/components/${tier}.md`))
);
write(
  "skill/democrito/components.md",
  GENERATED_HEADER + componentParts.join("\n\n---\n\n")
);
console.log("✓ skill/democrito/components.md");

// 4. agent-usage.md — concat AI tool guides (skip deep design/stitch guides)
const AI_TOOL_FILES = ["README.md", "terminal.md", "lovable.md", "replit.md", "cursor.md"];
const agentParts = AI_TOOL_FILES.map((f) =>
  flattenRelativeLinks(read(`docs/ai/${f}`))
);
write(
  "skill/democrito/agent-usage.md",
  GENERATED_HEADER + agentParts.join("\n\n---\n\n")
);
console.log("✓ skill/democrito/agent-usage.md");

console.log("\n✓ skill/ reference docs synced from docs/");
